import assert from "node:assert/strict";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { chromium } from "playwright-core";

// Real SQLite/service projections generated by scripts/phase3_delta_browser_fixtures.py.
// All navigation responses are synthetic; this runner cannot trigger providers.
const baseUrl = process.env.YIA_PHASE3_UI_URL ?? "http://127.0.0.1:5293/";
assert.match(baseUrl, /^http:\/\/127\.0\.0\.1:\d+\/$/);
const cases = JSON.parse(readFileSync(process.env.YIA_PHASE3_FIXTURES ?? "/tmp/phase3-delta-fixtures.json", "utf8"));
const artifacts = process.env.YIA_PHASE3_SCREENSHOTS ?? "/tmp/v1x-phase3-browser";
mkdirSync(artifacts, { recursive: true });
const browser = await chromium.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", headless: true });
const errors = [], external = [];
let scenarios = 0, navigations = 0;
const openLabels = {
  en: { content: "Open Content", intelligence: "Open Intelligence", topic: "Open Topic", source: "Open Following" },
  "zh-CN": { content: "打开内容", intelligence: "打开洞察", topic: "打开主题", source: "打开关注" },
};
const pageLabels = {
  en: { content: "Content", intelligence: "Intelligence", topic: "Topics", source: "Following" },
  "zh-CN": { content: "内容", intelligence: "洞察", topic: "主题", source: "关注" },
};
try {
  for (const language of ["zh-CN", "en"]) {
    for (const width of [320, 768, 1024, 1440]) {
      for (const [name, delta] of Object.entries(cases)) {
        const page = await browser.newPage({ viewport: { width, height: 1000 } });
        page.setDefaultTimeout(10000);
        const requests = [];
        page.on("pageerror", error => errors.push(`${name}/${language}/${width}: ${error}`));
        page.on("console", message => { if (["error", "warning"].includes(message.type())) errors.push(`${name}: ${message.text()}`); });
        page.on("request", request => {
          if (!request.url().startsWith(baseUrl)) external.push(request.url());
        });
        await page.addInitScript(lang => localStorage.setItem("yia.ui-language", lang), language);
        const video = { video_id: "content:fixture", channel_id: "channel", channel_name: "Synthetic source", title: "Content content:fixture", source_url: null, processing_status: "COMPLETE", published_at: delta.window_end, last_updated: delta.window_end };
        const intelligence = { status: "AVAILABLE", trusted: true, intelligence_id: "intelligence:fixture", claim_kind: "EVIDENCE_BACKED_STATEMENT", state: "CONFIRMED", card: { core_conclusion: "Synthetic existing Intelligence detail", user_relevant_information: [], important_new_information: [], meaningful_details: [], evidence_links: [], source_id: "source", source_display_name: "Synthetic source", source_url: null, video_id: video.video_id, video_title: video.title, original_video_url: null } };
        const topic = { topic_id: "topic:fixture", name: "真实关联主题 / Linked Topic", pinned: false, lifecycle: "ACTIVE", current_state: "UNRESOLVED", independence: "UNKNOWN", contributions: [], timeline: [], relations: [] };
        const source = { source_id: "source", display_name: "Source source", canonical_url: "https://www.youtube.com/channel/source", enabled: true, processing_policy: "STANDARD_INTELLIGENCE", last_error: null };
        await page.route("**/*", async route => {
          const url = route.request().url();
          if (!url.startsWith(baseUrl)) { external.push(url); return route.abort(); }
          const path = new URL(url).pathname;
          if (!path.startsWith("/api/")) return route.continue();
          requests.push(path);
          assert.equal(route.request().method(), "GET", `Unexpected mutation: ${path}`);
          const body = path === "/api/v1/knowledge-delta" ? { knowledge_delta: delta }
            : path === "/api/v1/dashboard" ? { intelligence: [], pinned_topics: [], weekly_v1: [], needs_attention: [], operations: { source_count: 1 } }
            : path === "/api/v1/videos" ? { videos: [video] }
            : path.endsWith("/evidence") ? { evidence: [] }
            : path.endsWith("/deep-analysis") ? { deep_analysis: { status: { availability: "NOT_QUALIFIED", qualified: false, reason_code: "MODEL_NOT_QUALIFIED" }, result: null } }
            : path.startsWith("/api/v1/videos/") ? { video, transcript: { status: "UNAVAILABLE" }, note: { v1: { status: "UNAVAILABLE" }, v2: { status: "UNAVAILABLE" } }, intelligence_result: { status: "NOT_PROCESSED" }, history: [] }
            : path === "/api/v1/intelligence" ? { intelligence: [intelligence] }
            : path.startsWith("/api/v1/intelligence/") ? { intelligence }
            : path === "/api/v1/topics" ? { topics: [topic] }
            : path.startsWith("/api/v1/topics/") ? { topic }
            : path === "/api/v1/sources" ? { sources: [source] }
            : path.startsWith("/api/v1/sources/") ? { source, policy: { initial_history_count: 5, per_run_max_new_videos: 5, focus_rules: [], ignore_rules: [], distillation_style: "BALANCED" }, schedules: [], recent_videos: [], source_runs: [] }
            : { saved: [], status: "UNAVAILABLE" };
          await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(body) });
        });
        await page.goto(`${baseUrl}#Home`);
        const region = page.getByRole("region", { name: language === "en" ? "What changed in the last 7 days?" : "最近 7 天发生了什么变化？" });
        await region.locator(".delta-window").waitFor();
        assert.equal(await page.locator("nav button").count(), 6);
        assert.equal(await page.locator(".knowledge-delta").count(), 1);
        const expectedItems = delta.categories.reduce((count, category) => count + category.items.length, 0);
        assert.equal(await region.locator(".delta-items li").count(), expectedItems);
        assert.ok(expectedItems <= 10);
        if (name === "empty") await region.getByText(language === "en" ? "No meaningful knowledge changes in the last 7 days." : "最近 7 天没有明显的知识变化。", { exact: true }).waitFor();
        if (name === "partial" || name === "unavailable") {
          assert.equal(await region.getByRole("alert").count(), 1);
          assert.equal(await region.locator(".delta-empty").count(), 0);
        }
        if (name === "boundary") {
          assert.deepEqual(delta.categories[0].items.map(item => item.target.id), ["at-end", "at-start"]);
        }
        const text = await region.innerText();
        assert.doesNotMatch(text, /since.*last|自上次|NEW_CONTENT|CONFIRMED|intelligence_added|SOURCE_CHECK_FAILED/);
        if (language === "zh-CN") assert.doesNotMatch(text, /Recorded state|Evidence set changed|Source checks resumed|Source discovery repeatedly blocked|Showing|Revisions in this window|Unavailable/);
        assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth), false, `${name}/${width}/${language} overflow`);
        await page.screenshot({ path: `${artifacts}/${name}-${language}-${width}.png`, fullPage: true });
        // Two languages exercise all four existing object targets with namespaced IDs.
        if (name === "mixed" && width === 1440) {
          for (const kind of ["content", "intelligence", "topic", "source"]) {
            const item = delta.categories.flatMap(category => category.items).find(item => item.target.kind === kind);
            assert.ok(item);
            const prefix = { content: "videos", intelligence: "intelligence", topic: "topics", source: "sources" }[kind];
            const opened = page.waitForResponse(response => new URL(response.url()).pathname === `/api/v1/${prefix}/${item.target.id}`);
            await region.getByRole("button", { name: `${openLabels[language][kind]}: ${item.title}`, exact: true }).first().click();
            await opened;
            await page.getByRole("heading", { name: pageLabels[language][kind], level: 1, exact: true }).waitFor();
            assert.ok(requests.includes(`/api/v1/${prefix}/${item.target.id}`), `${kind} object not opened`);
            if (kind === "source") await page.getByRole("dialog").getByRole("button", { name: language === "en" ? "Close" : "关闭", exact: true }).click();
            await page.getByRole("navigation").getByRole("button", { name: language === "en" ? "Home" : "首页", exact: true }).click();
            await region.locator(".delta-window").waitFor();
            navigations += 1;
          }
        }
        await page.close();
        scenarios += 1;
      }
    }
  }
  assert.deepEqual(external, []);
  assert.deepEqual(errors, []);
  const result = { scenarios, navigations, externalRequests: external.length, consoleErrorsAndWarnings: errors.length, screenshotDirectory: artifacts };
  writeFileSync(`${artifacts}/result.json`, JSON.stringify(result, null, 2));
  console.log(JSON.stringify(result));
} finally {
  await browser.close();
}
